#!/usr/bin/env bash
# Include real HA transport/recovery execution in application coverage.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../.."

cargo llvm-cov clean --workspace
cargo llvm-cov --workspace --all-features --locked --no-report
cargo llvm-cov run -p njorun-simulator --features qualification \
  --example preview --locked --no-report

(
  export CARGO_TARGET_DIR="$PWD/target/llvm-cov-target"
  # This shell program is generated by the repository-pinned cargo-llvm-cov.
  eval "$(cargo llvm-cov show-env --sh)"
  cargo build -p njorun-simulator --all-features --locked
  cargo build -p njorun-simulator --features qualification --example live_ui --locked
  export NJORUN_SIMULATOR="$CARGO_TARGET_DIR/debug/njorun-simulator"
  export NJORUN_LIVE_UI="$CARGO_TARGET_DIR/debug/examples/live_ui"
  uv run --locked python experiments/vertical-slice/qualify.py
)

cargo llvm-cov report --workspace --ignore-filename-regex '/tests/' \
  --fail-under-lines 90
